-- Backfill stage headings (ADR-028 D10) on every English guide page that
-- predates the stage lists: cant-pay-rent, discrimination, eviction-defense,
-- heat-not-working, landlord-entry, rent-increase, repairs-and-habitability,
-- resource-directory and security-deposits, live pages and their drafts.
--
-- The breaking-lease and locked-out drafts (ADR-028 phase 3) were drafted
-- with stages. The phase 3 handoff deferred "stages on existing drafts and
-- live pages"; this script closes that. Each statement was read in the local
-- Claude Code session (2026-10-11) and given one heading from its topic's
-- list in docs/ADR-028-stages-and-questions.md; a heading was never
-- invented. Statements keep their text, keys, citations and review stamps.
-- Within a page they are re-numbered so the stages run in the topic's order
-- and each heading renders once; inside a stage the old order is kept.
--
-- Keyed (playbook_id, statement key) and guarded by stage = '', so a
-- statement that gained a stage since the dump is left alone. Safe to run
-- more than once. The final SELECTs must show still_unstaged = 0,
-- bad_stage = 0 and pages_out_of_order = 0.
