UPDATE playbook_statements ps SET stage = v.stage, position = v.position
FROM v JOIN statements s ON s.key = v.key
WHERE ps.playbook_id = v.playbook_id AND ps.statement_id = s.id AND ps.stage = '';

-- Every page touched must now have every statement staged, in stage order.
SELECT t.slug AS topic, count(DISTINCT pb.id) AS pages, count(*) AS stmts,
  count(*) FILTER (WHERE ps.stage = '') AS still_unstaged,
  count(*) FILTER (WHERE NOT (ps.stage = ANY(t.stages))) AS bad_stage
FROM playbooks pb JOIN topics t ON t.id = pb.topic_id JOIN playbook_statements ps ON ps.playbook_id = pb.id
WHERE pb.language = 'en' AND pb.status IN ('published','draft') AND cardinality(t.stages) > 0
GROUP BY 1 ORDER BY 1;
-- Pages where a stage comes back after another (should be none).
SELECT count(*) AS pages_out_of_order FROM (
  SELECT ps.playbook_id FROM playbook_statements ps JOIN playbooks pb ON pb.id = ps.playbook_id JOIN topics t ON t.id = pb.topic_id
  WHERE pb.language = 'en' AND pb.status IN ('published','draft') AND cardinality(t.stages) > 0
  GROUP BY ps.playbook_id
  HAVING count(DISTINCT ps.stage) < (SELECT count(*) FROM (
    SELECT stage, lag(stage) OVER (ORDER BY position) AS prev FROM playbook_statements x WHERE x.playbook_id = ps.playbook_id) y
    WHERE prev IS NULL OR prev <> stage)
) z;

ROLLBACK;
